import {test,expect,type Page,type Locator} from '@playwright/test';
import {execFileSync} from 'node:child_process';
import {mkdirSync} from 'node:fs';
async function chooseRegistrationProfile(page:Page){const d=page.getByRole('dialog');await expect(d.getByRole('option',{name:'browser-profile',exact:true})).toHaveCount(1);await d.getByLabel('验证所用浏览器').selectOption('browser-profile');}
async function openVerificationBrowser(panel:Locator){await expect(panel).toBeVisible();const field=panel.getByLabel('验证所用浏览器');if(!await field.isVisible())await panel.getByRole('button',{name:/^(更换浏览器|选择浏览器)$/,exact:true}).click();await expect(field).toBeVisible();}
async function addedAccount(page:Page,name:string,reopen=true){await expect(page.getByRole('dialog')).toHaveCount(0);await expect(page.getByRole('status').filter({hasText:'账号已添加，验证请求已提交'})).toBeVisible();const row=page.getByRole('row').filter({hasText:name});await expect(row).toBeVisible();if(reopen)await row.getByRole('button',{name:'查看 / 编辑',exact:true}).click();}
async function editAccountNote(dialog:Locator,name:string){await dialog.locator('.account-note-editor>summary').click();await dialog.getByLabel('本地备注名称').fill(name);await dialog.getByRole('button',{name:'保存备注',exact:true}).click();await expect(dialog).toHaveCount(0);}
test('免登录打开工作台、清除Cookie后直接回到同一工作区，无用户与成员入口',async({page})=>{
  await page.goto('/');await expect(page.getByRole('heading',{name:'欢迎使用YOYO'})).toBeVisible();
  await expect(page.getByLabel('邮箱')).toHaveCount(0);await expect(page.getByLabel('密码')).toHaveCount(0);await expect(page.getByRole('button',{name:'退出登录'})).toHaveCount(0);
  await page.getByRole('link',{name:'工作区设置'}).click();await expect(page.getByRole('button',{name:'成员',exact:true})).toHaveCount(0);
  await page.getByRole('button',{name:'运营账号',exact:true}).click();await page.getByRole('button',{name:'添加账号',exact:true}).click();await page.getByLabel('小红书主页链接或内部账号 ID').fill('abcdefabcdefabcdefabcd01');await page.getByLabel('名称',{exact:false}).fill('真实标识测试账号');await chooseRegistrationProfile(page);await page.getByRole('button',{name:'添加并验证',exact:true}).click();await addedAccount(page,'真实标识测试账号',false);await expect(page.getByRole('cell',{name:'真实标识测试账号',exact:true})).toBeVisible();await expect(page.getByRole('row').filter({hasText:'真实标识测试账号'})).toContainText('公开身份已匹配');
  await page.getByRole('button',{name:'工作区',exact:true}).click();await page.getByLabel('名称',{exact:false}).fill('已修改工作区');await page.getByRole('button',{name:'保存设置'}).click();await expect(page.getByRole('status')).toContainText('已保存');
  await page.getByRole('button',{name:'运营账号',exact:true}).click();await page.context().clearCookies();await page.reload();await page.getByRole('button',{name:'运营账号',exact:true}).click();await expect(page.getByRole('cell',{name:'真实标识测试账号',exact:true})).toBeVisible();
});
test('服务错误可重试，请求凭据失效不返回登录页面',async({page})=>{
 await page.goto('/');await expect(page.getByRole('heading',{name:'欢迎使用YOYO'})).toBeVisible();
 await page.route('**/api/v1/settings',async route=>{await new Promise(r=>setTimeout(r,300));await route.fulfill({status:503,contentType:'application/json',body:JSON.stringify({error:{code:'SERVICE_UNAVAILABLE',message:'测试服务不可用'}})});});
 await page.getByRole('link',{name:'工作区设置'}).click();await expect(page.getByRole('status')).toContainText('正在加载');await expect(page.getByRole('alert')).toContainText('测试服务不可用');await page.unroute('**/api/v1/settings');await page.getByRole('button',{name:'重试'}).click();
 let fail=true;await page.route('**/api/v1/settings',route=>{if(route.request().method()==='PATCH'&&fail){fail=false;return route.fulfill({status:403,contentType:'application/json',body:JSON.stringify({error:{code:'CSRF_INVALID',message:'请求凭据已失效，请重试'}})});}return route.continue();});
 await page.getByRole('button',{name:'保存设置'}).click();await expect(page.getByRole('alert')).toContainText('请求凭据已失效');await expect(page.getByLabel('邮箱')).toHaveCount(0);await page.getByRole('button',{name:'保存设置'}).click();await expect(page.getByRole('status')).toContainText('已保存');
});

