 await d.getByRole('combobox',{name:'来源类型',exact:true}).selectOption('xhs_quality_note');await selectSourceBrowser(d);await d.getByRole('textbox',{name:'搜索关键词',exact:true}).fill('城市漫步，潮玩开箱');await d.getByRole('textbox',{name:'参考账号主页（选填）',exact:true}).fill('https://www.xiaohongshu.com/user/profile/aaaaaaaaaaaaaaaaaaaaaaaa');await expect(d).toContainText('不按搜索关键词过滤');await expect(d).toContainText('不会加入你的运营账号列表');await sourceFormScreens(page,d,'reference');await page.setViewportSize({width:320,height:1000});await d.locator('.source-create-scroll').evaluate(e=>e.scrollTop=e.scrollHeight);await d.screenshot({path:'docs/evidence/change033/screenshots/source-reference-help-320.png'});await page.setViewportSize({width:1440,height:1000});
 await d.getByRole('combobox',{name:'来源类型',exact:true}).selectOption('xhs_topic_signal');await expect(d.getByRole('textbox',{name:'搜索关键词',exact:true})).toHaveValue('城市漫步，潮玩开箱');await expect(d.getByRole('textbox',{name:'参考账号主页（选填）',exact:true})).toHaveCount(0);await expect(d).toContainText('优先寻找较新的话题线索');await expect(d).toContainText('短代码是浏览器连接标识');await sourceFormScreens(page,d,'search');
 await d.getByRole('combobox',{name:'来源类型',exact:true}).selectOption('weibo_hot');await d.getByRole('button',{name:'添加来源',exact:true}).click();await expect(d).toHaveCount(0);expect(posts.at(-1)).toEqual({name:'明确合成微博来源设计',source_type:'weibo_hot',platform:'weibo',provider:'weibo_web',enabled:false,config:{}});await expect(page.getByRole('status').filter({hasText:'来源已添加，尚未采集'})).toBeVisible();
 await page.getByRole('button',{name:'添加来源',exact:true}).click();await d.getByLabel('来源名称').fill('明确合成逐词搜索');await d.getByRole('combobox',{name:'来源类型',exact:true}).selectOption('xhs_quality_note');await selectSourceBrowser(d);await d.getByRole('textbox',{name:'搜索关键词',exact:true}).fill('旅行，潮玩\n旅行');await d.getByRole('textbox',{name:'参考账号主页（选填）',exact:true}).fill('这条隐藏草稿不应提交');await d.getByRole('combobox',{name:'来源类型',exact:true}).selectOption('xhs_topic_signal');await d.getByRole('button',{name:'添加来源',exact:true}).click();await expect(d).toHaveCount(0);expect(posts.at(-1).config).toEqual({profile:'browser-profile',keywords:['旅行','潮玩']});expect(extraWrites).toEqual([]);
