test('新增来源校验：关键词数量/参考主页格式重复错误保留输入，失败可重试且提交中不能关闭',async({page})=>{
 const posts:any[]=[];page.on('request',r=>{if(r.method()==='POST'&&r.url().endsWith('/source-connections'))posts.push(r.postDataJSON());});await page.goto('/#topics');await page.getByRole('button',{name:'添加来源',exact:true}).click();const d=page.getByRole('dialog',{name:'添加来源',exact:true});await d.getByLabel('来源名称').fill('明确合成参考输入校验');await d.getByRole('combobox',{name:'来源类型',exact:true}).selectOption('xhs_quality_note');await selectSourceBrowser(d);const keywords=d.getByRole('textbox',{name:'搜索关键词',exact:true}),refs=d.getByRole('textbox',{name:'参考账号主页（选填）',exact:true}),submit=d.getByRole('button',{name:'添加来源',exact:true});
 await keywords.fill(Array.from({length:11},(_,i)=>'关键词'+i).join(','));await submit.click();await expect(d.getByRole('alert')).toContainText('最多填写10个关键词');expect(posts).toHaveLength(0);await keywords.fill(' , ');await submit.click();await expect(d.getByRole('alert')).toContainText('至少填写1个');await keywords.fill('旅行、潮玩\nIP,旅行');
 await refs.fill('昵称不是主页');await submit.click();await expect(d.getByRole('alert')).toContainText('不是有效的个人主页');await expect(refs).toHaveValue('昵称不是主页');await refs.fill('aaaaaaaaaaaaaaaaaaaaaaaa\nhttps://www.xiaohongshu.com/user/profile/AAAAAAAAAAAAAAAAAAAAAAAA');await submit.click();await expect(d.getByRole('alert')).toContainText('参考账号重复');await refs.fill('a'.repeat(24)+'\n'+'b'.repeat(24)+'\n'+'c'.repeat(24));await submit.click();await expect(d.getByRole('alert')).toContainText('最多添加2个参考账号');expect(posts).toHaveLength(0);
 await refs.fill('https://www.xiaohongshu.com/user/profile/AAAAAAAAAAAAAAAAAAAAAAAA?xsec_token=synthetic-only\n'+'b'.repeat(24));let release!:()=>void;const hold=new Promise<void>(r=>release=r);let failed=false;await page.route('**/api/v1/source-connections',async r=>{if(r.request().method()==='POST'&&!failed){failed=true;await hold;return r.fulfill({status:503,json:{error:{code:'SERVICE_UNAVAILABLE',message:'合成新增暂不可用'}}});}return r.continue();});
 await submit.click();await expect(d.getByRole('button',{name:'关闭详情',exact:true})).toBeDisabled();await expect(d.getByRole('combobox',{name:'来源类型',exact:true})).toBeDisabled();await page.keyboard.press('Escape');await expect(d).toBeVisible();release();await expect(d.getByRole('alert')).toContainText('合成新增暂不可用');await expect(d.getByRole('alert')).toBeInViewport();await expect(keywords).toHaveValue('旅行、潮玩\nIP,旅行');await expect(d.getByRole('combobox',{name:'采集使用的浏览器',exact:true})).toHaveValue('browser-profile');await submit.click();await expect(d).toHaveCount(0);expect(posts).toHaveLength(2);expect(posts[0].config).toEqual({profile:'browser-profile',keywords:['旅行','潮玩','IP'],reference_accounts:['a'.repeat(24),'b'.repeat(24)]});expect(posts[1]).toEqual(posts[0]);expect(JSON.stringify(posts)).not.toContain('xsec_token');
});
test('新增来源浏览器未连接：仅小红书读取列表，必填提示阻止保存，刷新后可恢复',async({page})=>{
 let fail=true,reads=0,posts=0;await page.route('**/api/v1/account-browser-profiles',r=>{reads++;return fail?r.fulfill({status:503,json:{error:{code:'BROWSER_UNAVAILABLE',message:'合成浏览器未连接'}}}):r.fulfill({json:{data:{items:[{id:'browser-profile'}]}}});});page.on('request',r=>{if(r.method()==='POST'&&r.url().endsWith('/source-connections'))posts++;});await page.goto('/#topics');await page.getByRole('button',{name:'添加来源',exact:true}).click();const d=page.getByRole('dialog',{name:'添加来源',exact:true});await d.getByLabel('来源名称').fill('明确合成浏览器选择');expect(reads).toBe(0);await d.getByRole('combobox',{name:'来源类型',exact:true}).selectOption('xhs_topic_signal');await expect(d).toContainText('合成浏览器未连接');await d.getByRole('textbox',{name:'搜索关键词',exact:true}).fill('旅行');await d.getByRole('button',{name:'添加来源',exact:true}).click();const browser=d.getByRole('combobox',{name:'采集使用的浏览器',exact:true});expect(await browser.evaluate((e:HTMLSelectElement)=>e.validity.valueMissing)).toBe(true);expect(posts).toBe(0);fail=false;await d.getByRole('button',{name:'刷新列表',exact:true}).click();await selectSourceBrowser(d);await d.getByRole('button',{name:'添加来源',exact:true}).click();await expect(d).toHaveCount(0);expect(posts).toBe(1);expect(reads).toBe(2);
});

