 let submitted:any;await page.route('**/api/v1/topic-generations',async r=>{submitted=r.request().postDataJSON();return r.fulfill({status:202,json:{data:{request_id:'a5000000-0000-4000-8000-000000000001',state:'queued'}}});});await d.getByRole('button',{name:'提交生成',exact:true}).click();await expect(d).toHaveCount(0);expect(Object.keys(submitted).sort()).toEqual(['account_id','columns','window']);expect(submitted.columns).toEqual(['日常观察']);
